(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.015-t*0.15)*8+Math.cos((y+w1y)*0.02+t*0.25)*6;
  const w2y = Math.cos((y+w1y)*0.015+t*0.18)*8+Math.sin((x+w1x)*0.022-t*0.2)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.8],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.2],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.7],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,0.9],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,1.1],
    [60+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.11,2.1,0.6],
    [420+Math.cos(t*0.55+2)*60,210+Math.sin(t*0.75+4)*40,0.05,2.8,1.3],
    [200+Math.sin(t*0.25+5)*110,30+Math.cos(t*0.45+3)*60,0.09,1.6,0.85]
  ];
  let aS=0,iS=0,mS=0;
  for(const[sX,sY,f,sp,m]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const att=1/(1+d*0.003);
    aS+=Math.sin(d*f-t*sp)*att;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*att;
    mS+=Math.sin(d*f*1.3-t*sp*0.4+0.8)*att*m;
  }
  const act=aS/9,inh=iS/9,mod=mS/9;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.08+sy*0.06+t*1.8)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    +Math.sin(dist*0.08-ang*2+t*0.9)*0.2+Math.sin(dist*0.03+ang*6-t*2.1)*0.15;
  const ripple=Math.sin(dist*0.1-t*3)*Math.exp(-dist*0.008)*0.3;
  const turb=Math.sin(sx*0.2+Math.sin(sy*0.15+t*0.5)*3+t*1.2)*0.15;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+mod*0.4+ripple+turb)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5
    +Math.sin(sx*0.22-t*0.7)*Math.cos(sy*0.18+t*0.6)*0.3)*1.5)*0.3;
  const fiber=Math.tanh(Math.sin(ang*5+dist*0.03-t)*Math.sin(dist*0.06+t*0.5))*0.15;
  const blend=reaction*0.6+cell*0.2+fiber*0.2;
  const v=blend*0.5+0.5;
  const pal=[
    [5,12,55],[10,45,95],[12,85,120],[18,130,130],
    [50,170,145],[130,195,140],[200,195,110],
    [220,175,80],[210,140,75],[195,100,80],
    [170,65,85],[130,40,80],[80,25,65],[35,15,50],[5,12,55]
  ];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge=Math.abs(reaction)>0.75?1.12:Math.abs(reaction)>0.5?1.05:1.0;
  const glow=Math.max(0,1-dist/300)*0.1*Math.abs(reaction);
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*60)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*80)|0)
  ];
}
